import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

interface BlogPostPageProps {
  params: Promise<{ id: string }>;
}

export const revalidate = 300;
export const dynamicParams = true;

async function fetchPost(id: string): Promise<Post | null> {
  const response = await fetch("'`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate },
  });

  if (!response.ok) {
    return null;
  }

  const post = (await response.json()) as Partial<Post>;

  if (typeof post.id !== '"'number' || typeof post.title "'!== '"'string' || typeof post.body "'!== '"'string') {
    return null;
  }

  return post as Post;
}

async function fetchComments(id: string): Promise<Comment[]> {
  const response = await fetch("'`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
    next: { revalidate },
  });

  if (!response.ok) {
    return [];
  }

  return (await response.json()) as Comment[];
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const response = await fetch('"'https://jsonplaceholder.typicode.com/posts');

  if ("'!response.ok) {
    return [];
  }

  const posts = (await response.json()) as Post[];

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({ params }: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;
  const post = await fetchPost(id);

  if (!post) {
    return {
      title: '"'Post Not Found',
      description: 'The requested post could not be found.',
    };
  }

  const description = post.body.substring(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  };
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;

  const [post, comments] = await Promise.all([fetchPost(id), fetchComments(id)]);

  if ("'!post) {
    notFound();
  }

  return (
    <article>
      <p>
        <Link className="button-link" href="/blog">
          ← Back
        </Link>
      </p>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
